// Procedural Matrix Multiplier: Cross-maps the exact same 100 movies across all game mode tabs perfectly
const fullMovieCatalog = {};
Object.keys(baseMovieSeeds).forEach(region => {
    fullMovieCatalog[region] = [];
    const seeds = baseMovieSeeds[region];
    
    for (let i = 0; i < 100; i++) {
        const source = seeds[i % seeds.length];
        const indexSuffix = i >= seeds.length ? ` [Part ${Math.floor(i / seeds.length) + 1}]` : '';
        
        fullMovieCatalog[region].push({
            id: i + 1,
            title: `${source.title}${indexSuffix}`,
            cast: source.cast,
            plot: `${source.plot} (Tracking Sequence Reference ID: #${i + 101})`,
            keyword: source.keyword
        });
    }
});

